name: CI

on:
  pull_request:
  push:
    branches: [main]

jobs:
  validate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@8e8c483db84b4bee98b60c0593521ed34d9990e8 # v6
      - uses: jdx/mise-action@c1ecc8f748cd28cdeabf76dab3cccde4ce692fe4 # v4

      - name: Validate root config
        run: mise run validate-renovate-root

      - name: Validate presets
        run: mise run validate-renovate-presets
 */
async function synchronizeDirectory(
  backend: BackendProtocolV2,
  directory: Directory,
  root: string,
  labels: IndexLabels,
  conceptType: string,
): Promise<void> {
  const files: Link[] = [];
  const directories: Link[] = [];

  for (const entry of directory.entries) {
    const name = entryName(entry);
    if (!name || name.startsWith(".")) continue;

    if (entry.is_dir) {
      directories.push({ href: `${encodeURIComponent(name)}/`, label: name });
      continue;
    }
    if (
      path.posix.extname(name).toLowerCase() !== ".md" ||
      EXCLUDED_FILES.has(name)
    ) {
      continue;
    }

    const filePath = path.posix.join(directory.path, name);
    const content = await normalizeConceptFile(backend, filePath, conceptType);
    const metadata = readIndexMetadata(content);
    files.push({
      description: metadata.description,
      href: encodeURIComponent(name),
      label: metadata.title ?? path.posix.basename(name, ".md"),
    });
  }

  const indexPath = path.posix.join(directory.path, INDEX_FILE);
  const content = renderIndex(
    files,
    directories,
    directory.path === root,
    labels,
  );
  const existing = directory.entries.some(
    (entry) => !entry.is_dir && entryName(entry) === INDEX_FILE,
  )
    ? await readText(backend, indexPath)
    : null;
  if (existing === content) return;

  const result = existing
    ? await backend.edit(indexPath, existing, content)
    : await backend.write(indexPath, content);
  if (result.error) {
    throw new Error(`Unable to write ${indexPath}: ${result.error}`);
  }
}

/**
 * Renders a complete deterministic index document.
 */
function renderIndex(
  files: Link[],
  directories: Link[],
  isRoot: boolean,
  labels: IndexLabels,

/**
 * Options for {@link OpenWikiLocalShellBackend}, extending the deepagents shell backend options.
 */
type OpenWikiBackendOptions = LocalShellBackendOptions & {
  /**
   * Confine writes to the `openwiki/` docs tree.
   *
   * @default false
   */
  docsOnly?: boolean;

  /**
   * Rules that exclude paths from all agent filesystem/shell access.
   *
   * @default an inactive ruleset (no exclusions)
   */
  openWikiIgnore?: OpenWikiIgnore;

  /**
   * The doc-generation output target, which relaxes the docs-only write check
   * for `local-wiki` runs.
   *
   * @default "repository"
   */
  outputMode?: OpenWikiOutputMode;

  /**
   * Exact generated pages this backend may mutate in repository docs-only mode.
   *
   * `undefined` preserves the existing repository writer behavior. An empty
   * array creates a read-only generated-docs backend.
   */
  writableWikiPages?: readonly string[];
};

