        backend,
        outputMode,
        labels,
        conceptType,
        prepared: preparedWiki,
        at: now,
        claimSources: claimSources?.(),
        runOperation: (operation, task) =>
          inStage("finalize", task, {
            errorClass: "okf_error",
            errorDetail: operation,
